const C = window.INVITE;
const $ = s => document.querySelector(s);
document.querySelectorAll('[data-date]').forEach(x=>x.textContent=C.dateLabel);
document.querySelectorAll('[data-host]').forEach(x=>x.textContent=C.host);
document.querySelectorAll('[data-time]').forEach(x=>x.textContent=C.time);
document.querySelectorAll('[data-venue]').forEach(x=>x.textContent=C.venue);
$('#address').textContent=C.address;
const roles=$('#roles');
C.roles.forEach(([name,desc,icon])=>{const label=document.createElement('label'),radio=document.createElement('input'),span=document.createElement('span');radio.type='radio';radio.name='role';radio.value=name;radio.required=true;const i=document.createElement('i'),b=document.createElement('b'),small=document.createElement('small');i.textContent=icon;i.setAttribute('aria-hidden','true');b.textContent=name;small.textContent=desc;span.append(i,b,small);label.append(radio,span);roles.append(label)});
function updateCountdown(){let s=Math.max(0,Math.floor((new Date(C.date)-Date.now())/1000));for(const [id,n] of [['days',86400],['hours',3600],['minutes',60],['seconds',1]]){const v=Math.floor(s/n);s%=n;$('#'+id).textContent=String(v).padStart(2,'0')}if(new Date(C.date)<=new Date())$('#countdown-caption').textContent='The wait is over. Let the good times begin.'}
updateCountdown();setInterval(updateCountdown,1000);
const calendarDate=s=>new Date(s).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
$('#calendar').href='https://calendar.google.com/calendar/render?'+new URLSearchParams({action:'TEMPLATE',text:C.title+' · Diwali',dates:calendarDate(C.date)+'/'+calendarDate(C.end),details:'Post dinner scenes. Traditional attire. BYOB. A night of games and festive fun.',location:C.venue+' — '+C.address,ctz:'Asia/Kolkata'});
$('#open-invite').onclick=()=>{$('#open-invite').setAttribute('aria-expanded','true');$('#invitation').scrollIntoView({behavior:'smooth'})};
function recipient(){const raw=C.whatsappNumber.trim();return /^\+?[1-9]\d{7,14}$/.test(raw)?raw.replace(/^\+/,''):null}
function notice(message){$('#notice').textContent=message;$('#notice').hidden=false;setTimeout(()=>$('#notice').hidden=true,9000)}
$('#directions').onclick=()=>{const number=recipient();if(!number){notice('The host’s WhatsApp number hasn’t been added yet. Please check back for directions.');return}window.location.href='https://wa.me/'+number+'?text='+encodeURIComponent('Hi! Could you share directions to '+C.title+' at '+C.venue+'?')};
$('#rsvp').onsubmit=e=>{e.preventDefault();const name=$('#guest-name').value.trim(),attendance=$('input[name="attendance"]:checked'),role=$('input[name="role"]:checked');const error=$('#form-error');if(!name||!attendance||!role){error.textContent=!name?'Please enter your name.':!attendance?'Let us know whether you’re coming.':'Pick your party persona to complete your RSVP.';if(!name)$('#guest-name').focus();else if(!attendance)$('input[name="attendance"]').focus();else $('input[name="role"]').focus();return}error.textContent='';$('#card-name').textContent=name;$('#card-role').textContent=role.value;$('#card-attendance').textContent=attendance.value==='Yes'?'Dealt in. Iss Diwali, Fursat manao.':attendance.value==='Maybe'?'A little undecided. A little tempted.':'We’ll miss you at the table.';$('#card-event').textContent=C.title+' · '+C.dateLabel+' · '+C.time;$('#guest-card').hidden=false;const number=recipient();if(!number){error.textContent='Your card is ready! The host must add their fixed WhatsApp number in config.js before RSVPs can be sent.';$('#guest-card').scrollIntoView({behavior:'smooth',block:'center'});return}const message=['🪔 RSVP · '+C.title,'','Guest name: '+name,'Attendance: '+attendance.value,'Preferred game / crew role: '+role.value,'','Event: '+C.dateLabel,'Time: '+C.time,'Venue: '+C.venue,'Address: '+C.address].join('\n');window.location.href='https://wa.me/'+number+'?text='+encodeURIComponent(message);notice('Your RSVP is ready in WhatsApp. Press Send there to send it to the host.')};
if('IntersectionObserver' in window){document.documentElement.classList.add('js-animate');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:0.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
